<main class="main"><div class="main__inner"><div class="module-page"><header class="module-page__header"><div><h1>Promote Students</h1><p>Transactionally move selected students and retain audit history.</p></div></header><form class="filter-bar filter-bar--compact" method="get"><div class="module-field"><label>Source Class</label><select class="module-select" name="from_class" required><option value="">Select Class</option><?php foreach($classes as$c):?><option value="<?= $c['id'] ?>" <?= $selectedClass==$c['id']?'selected':'' ?>><?= e($c['name']) ?></option><?php endforeach ?></select></div><button class="btn btn--secondary">Load Students</button></form><?php if($selectedClass):?><form method="post" action="<?= url('/admin/students/promotions') ?>"><?= csrf_field() ?><input type="hidden" name="from_class" value="<?= $selectedClass ?>"><section class="module-card"><div class="module-card__body"><label class="check-row"><input type="checkbox" onclick="document.querySelectorAll('[name=\'students[]\']').forEach(x=>x.checked=this.checked)"> Select All</label><div class="table-scroll"><table class="data-table"><thead><tr><th>Select</th><th>Registration</th><th>Student</th></tr></thead><tbody><?php foreach($students as$s):?><tr><td><input type="checkbox" name="students[]" value="<?= $s['id'] ?>"></td><td><?= e($s['registration_no']) ?></td><td><?= e($s['student_name']) ?></td></tr><?php endforeach ?></tbody></table></div><div class="module-field"><label>Target Class</label><select class="module-select" name="to_class" required><option value="">Select target</option><?php foreach($classes as$c):if($c['id']==$selectedClass)continue;?><option value="<?= $c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach ?></select></div><button class="btn btn--primary" onclick="return confirm('Promote selected students?')">Promote Selected</button></div></section></form><?php endif ?><section class="module-card"><header class="module-card__header"><h2>Promotion History</h2></header><div class="module-card__body"><div class="table-scroll"><table class="data-table"><thead><tr><th>Student</th><th>From</th><th>To</th><th>Date</th><th>By</th></tr></thead><tbody><?php foreach($history as$h):?><tr><td><?= e($h['registration_no'].' — '.$h['student_name']) ?></td><td><?= e($h['from_class']) ?></td><td><?= e($h['to_class']) ?></td><td><?= e($h['promoted_at']) ?></td><td><?= e($h['promoted_by_name']) ?></td></tr><?php endforeach ?></tbody></table></div></div></section></div></div></main>
